'use strict'

// Tray icon source (P1, 2026-10-18 snow migration §12.2).
//
// Why this is a module: main.js sits at a hard line ceiling, so the "which icon
// does the tray need right now" decision lives here and main.js only asks for a
// prepared image. The rule itself is small but has three traps worth naming:
//
//   1. Windows does not recolor tray bitmaps, so a dark taskbar needs its own
//      asset (assets/icon-dark.png, generated by generate-icon.js);
//   2. `settings.theme === 'system'` means the *window* theme follows the OS, and
//      the tray must follow the OS too - reading settings.theme alone would pin
//      the tray to whatever the store says even after the user switches the OS
//      appearance at sunset;
//   3. a missing/garbled asset must not crash the tray: nativeImage is empty on
//      failure and Tray(empty) throws on some platforms, so the fallback chain
//      ends at a truly empty image only when even the light asset failed.
//
// The size is the same 24px logical size main.js already used. Windows scales it
// by the display DPI itself, and passing a 16px bitmap here would look blurry on
// 150% displays.

const TRAY_ICON_SIZE = 24

const ICON_FILES = Object.freeze({
  light: 'icon.png',
  dark: 'icon-dark.png'
})

// Resolves the theme that is actually painted. `theme` is the stored setting:
// 'light' / 'dark' / 'system'. `systemPrefersDark` is what Electron's nativeTheme
// reports for the OS (main.js passes `nativeTheme.shouldUseDarkColors`).
function resolveTrayIconTheme(theme, systemPrefersDark) {
  if (theme === 'light' || theme === 'dark') return theme
  return systemPrefersDark === true ? 'dark' : 'light'
}

/**
 * Build the tray image for the current theme.
 *
 * @param {object} options
 *   nativeImage   Electron nativeImage (required)
 *   directory     absolute assets directory
 *   theme         stored settings.theme ('light' | 'dark' | 'system')
 *   systemPrefersDark  nativeTheme.shouldUseDarkColors
 *   size          optional logical size, defaults to 24
 * @returns {{ image: object, theme: string, file: string, resized: boolean }}
 */
function createTrayIconImage({
  nativeImage,
  directory,
  theme = 'system',
  systemPrefersDark = false,
  size = TRAY_ICON_SIZE
} = {}) {
  if (!nativeImage || typeof nativeImage.createFromPath !== 'function') {
    throw new TypeError('Tray icon creation requires Electron nativeImage')
  }
  if (typeof directory !== 'string' || !directory) {
    throw new TypeError('Tray icon creation requires an assets directory')
  }
  const path = require('node:path')
  const resolvedTheme = resolveTrayIconTheme(theme, systemPrefersDark)
  const requestedSize = Number.isFinite(Number(size)) && Number(size) > 0 ? Math.round(Number(size)) : TRAY_ICON_SIZE
  // Dark first for dark, light first for light; the other one is the fallback so
  // a missing generated asset still produces a usable tray instead of an empty
  // square (the two assets are the same artwork, only the fill differs).
  const order = resolvedTheme === 'dark' ? ['dark', 'light'] : ['light', 'dark']
  for (const candidate of order) {
    const file = ICON_FILES[candidate]
    const image = nativeImage.createFromPath(path.join(directory, file))
    if (!image || (typeof image.isEmpty === 'function' && image.isEmpty())) continue
    return {
      image: image.resize({ width: requestedSize, height: requestedSize }),
      theme: resolvedTheme,
      file,
      resized: true
    }
  }
  return {
    image: typeof nativeImage.createEmpty === 'function' ? nativeImage.createEmpty() : null,
    theme: resolvedTheme,
    file: '',
    resized: false
  }
}

module.exports = {
  ICON_FILES,
  TRAY_ICON_SIZE,
  createTrayIconImage,
  resolveTrayIconTheme
}
